:root {
  --bg: #0f1115;
  --surface: #1a1d24;
  --surface-2: #232732;
  --border: #2c313d;
  --text: #e6e8ee;
  --muted: #9aa2b1;
  --accent: #5b8cff;
  --accent-hover: #4a7bf0;
  --danger: #ff5c6c;
  --star: #ffd05b;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 24px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand { display: flex; align-items: center; gap: 10px; }
.brand h1 { font-size: 1.15rem; margin: 0; letter-spacing: 0.3px; }
.logo { font-size: 1.4rem; }

.search-wrap { flex: 1; max-width: 560px; }
#search {
  width: 100%;
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 0.95rem;
}
#search:focus { outline: none; border-color: var(--accent); }

.btn {
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  padding: 9px 16px;
